let thold = 5;
let spifac = 1.05;
let drag = 0.01;
let big = 500;
ball bodies[] = new Array(big);
let mX;
let mY;
function setup() {
  createCanvas(360, 640);
  strokeWeight(1);
  smooth();
  stroke(255,205, 0, 10);
  for(i = 0; i < big; i++) {
    bodies[i] = new ball();
  }
}
function draw() {
  if(mousePressed) {
    background(0);

    mX += 0.3 * ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - mX);
    mY += 0.3 * ((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - mY);
  }
   mX += 0.3 * ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - mX);
    mY += 0.3 * ((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - mY);
  for(i = 0; i < big; i++) {
    bodies[i].render();
  }
  filter(BLUR,1);
}
class ball {
  X;
  Y;
  Xv;
  Yv;
  pX;
  pY;
  w;
  constructor() {
    X = random(screen.width);
    Y = random(screen.height);
    w = random(1 / thold, thold);
  }
  function render() {
    if(!mousePressed) {
      Xv /= spifac;
      Yv /= spifac;
    }
    Xv += drag * (mX - X) * w;
    Yv += drag * (mY - Y) * w;
    X += Xv;
    Y += Yv;
    line(X, Y, pX, pY);
    pX = X;
    pY = Y;
  }
}

